#include <furi.h>
#include <gui/gui.h>
#include <input/input.h>
#include <math.h>
#include <stdlib.h>
#include <stdio.h>
#define N 16
static const char* map[N]={"################","#..............#","#.##..###..###.#","#.##..###..###.#","#..............#","#..............#","#.###..##..###.#","#.###..##..###.#","#..............#","#..............#","#.##..###..###.#","#.##..###..###.#","#..............#","#..###....###..#","#..............#","################"};
typedef struct {float x,y,a; int ride; unsigned phase; bool chord; float vx[8],vy[8]; float depth[128]; bool keys[6],car,quit; unsigned cash,mission; FuriMessageQueue* q; FuriMutex* lock;} Game;
static bool wall(float x,float y){int a=(int)x,b=(int)y;return x<0||y<0||a>=N||b>=N||map[b][a]=='#';}
static void vehicle(Canvas* c,int x,int y,int w,int h,bool bike){if(w<3||h<3)return;canvas_set_color(c,ColorWhite);canvas_draw_box(c,x,y,w,h);canvas_set_color(c,ColorBlack);if(bike){canvas_draw_disc(c,x+w/4,y+h-2,2);canvas_draw_disc(c,x+3*w/4,y+h-2,2);canvas_draw_line(c,x+w/4,y+h-2,x+w/2,y);canvas_draw_line(c,x+w/2,y,x+3*w/4,y+h-2);canvas_draw_line(c,x+w/2,y,x+w-1,y);}else{canvas_draw_rbox(c,x,y+h/3,w,h-h/3,2);canvas_draw_frame(c,x+w/5,y,w*3/5,h/2);canvas_set_color(c,ColorWhite);canvas_draw_line(c,x+2,y+h/2,x+w/3,y+h/2);canvas_draw_line(c,x+2*w/3,y+h/2,x+w-3,y+h/2);canvas_set_color(c,ColorBlack);}}
static void hero(Canvas* c,unsigned phase){int a=(phase/3)%4;int step=a==0?0:a==1?3:a==2?0:-3;canvas_draw_disc(c,64,33,4);canvas_set_color(c,ColorWhite);canvas_draw_line(c,61,34,67,34);canvas_set_color(c,ColorBlack);canvas_draw_rbox(c,58,38,12,10,2);canvas_set_color(c,ColorWhite);canvas_draw_line(c,60,39,68,39);canvas_draw_line(c,64,40,64,46);canvas_set_color(c,ColorBlack);canvas_draw_line(c,58,40,55,46+step);canvas_draw_line(c,69,40,72,46-step);canvas_draw_box(c,60,48,3,5);canvas_draw_box(c,65,48,3,5);canvas_draw_line(c,61,52,59-step,53);canvas_draw_line(c,66,52,68+step,53);}
static void draw(Canvas* c,void* ctx){Game* g=ctx;furi_mutex_acquire(g->lock,FuriWaitForever);canvas_clear(c);float dx=cosf(g->a),dy=sinf(g->a);float cx=g->x,cy=g->y;for(float d=.1f;d<.9f;d+=.1f){if(wall(g->x-d*dx,g->y-d*dy))break;cx=g->x-d*dx;cy=g->y-d*dy;}
for(int x=0;x<128;x+=2){float off=(x-64)/64.f*.65f;float rx=dx-dy*off,ry=dy+dx*off;float d=.05f;while(d<15&&!wall(cx+rx*d,cy+ry*d))d+=.045f;g->depth[x]=g->depth[x+1]=d;int h=(int)(35/d);if(h>52)h=52;int top=28-h/2;canvas_draw_line(c,x,top,x,top+h);canvas_draw_line(c,x+1,top,x+1,top+h);if(((int)((cx+rx*d)*6)+(int)((cy+ry*d)*6))%4==0){canvas_set_color(c,ColorWhite);for(int yy=top+3;yy<top+h-2;yy+=6)canvas_draw_dot(c,x+1,yy);canvas_set_color(c,ColorBlack);}}
for(int i=0;i<4;i++){int y=35+i*i*2;canvas_draw_line(c,62,y,65,y);}
for(int i=0;i<8;i++){if(i==g->ride)continue;float ax=g->vx[i]-cx,ay=g->vy[i]-cy,z=ax*dx+ay*dy,side=-ax*dy+ay*dx;if(z<.2f)continue;int sx=64+(int)(side*98/z);if(sx<4||sx>123||z>g->depth[sx])continue;int w=(int)((i%3==2?9:18)/z),h=(int)(12/z);if(w>28)w=28;if(h>18)h=18;int bottom=28+(int)(17/z);if(bottom>53)bottom=53;if(sx-w/2<0||sx+w/2>127)continue;vehicle(c,sx-w/2,bottom-h,w,h,i%3==2);}
if(g->ride>=0)vehicle(c,53,36,22,17,g->ride%3==2);else hero(c,g->phase);
canvas_set_color(c,ColorWhite);canvas_draw_box(c,0,0,128,9);canvas_draw_box(c,0,54,128,10);canvas_set_color(c,ColorBlack);canvas_set_font(c,FontSecondary);char s[40];snprintf(s,sizeof(s),"$%u  %s",g->cash,g->ride<0?"JASON":g->ride%3==2?"BIKE":"CAR");canvas_draw_str(c,1,8,s);canvas_draw_str(c,1,63,"HP100");snprintf(s,sizeof(s),"M%u: %d,%d",g->mission+1, g->mission%2?1:14,g->mission%2?1:14);canvas_draw_str(c,48,63,s);canvas_draw_frame(c,105,10,22,22);for(int y=0;y<N;y++)for(int x=0;x<N;x++)if(map[y][x]=='#')canvas_draw_dot(c,108+x,13+y);canvas_draw_disc(c,108+(int)g->x,13+(int)g->y,1);furi_mutex_release(g->lock);}
static void input(InputEvent* e,void* ctx){Game* g=ctx;furi_message_queue_put(g->q,e,0);}
int32_t gta_main(void* p){UNUSED(p);Game* g=calloc(1,sizeof(Game));if(!g)return -1;g->x=1.5f;g->y=1.5f;g->ride=-1;float vx[8]={3.5,7.5,12.5,2.5,9.5,13.5,5.5,11.5},vy[8]={1.5,4.5,5.5,8.5,9.5,12.5,14.5,1.5};for(int i=0;i<8;i++){g->vx[i]=vx[i];g->vy[i]=vy[i];}g->q=furi_message_queue_alloc(16,sizeof(InputEvent));g->lock=furi_mutex_alloc(FuriMutexTypeNormal);ViewPort* v=view_port_alloc();view_port_draw_callback_set(v,draw,g);view_port_input_callback_set(v,input,g);Gui* gui=furi_record_open(RECORD_GUI);gui_add_view_port(gui,v,GuiLayerFullscreen);while(!g->quit){InputEvent e;bool got=furi_message_queue_get(g->q,&e,30)==FuriStatusOk;furi_mutex_acquire(g->lock,FuriWaitForever);if(got){if(e.key==InputKeyBack&&e.type==InputTypeShort)g->quit=true;if(e.key<6){if(e.type==InputTypePress)g->keys[e.key]=true;if(e.type==InputTypeRelease)g->keys[e.key]=false;}}bool combo=g->keys[InputKeyDown]&&g->keys[InputKeyOk];if(combo&&!g->chord){if(g->ride>=0){g->ride=-1;float ex=g->x-sinf(g->a)*.65f,ey=g->y+cosf(g->a)*.65f;if(!wall(ex,ey)){g->x=ex;g->y=ey;}}else{float best=1.44f;int near=-1;for(int i=0;i<8;i++){float ax=g->x-g->vx[i],ay=g->y-g->vy[i],d=ax*ax+ay*ay;if(d<best){best=d;near=i;}}if(near>=0){g->ride=near;g->x=g->vx[near];g->y=g->vy[near];}}}g->chord=combo;if(g->keys[InputKeyLeft])g->a-=.09f;if(g->keys[InputKeyRight])g->a+=.09f;float speed=(g->ride>=0?(g->ride%3==2?.20f:.15f):g->keys[InputKeyOk]?.11f:.07f)*(g->keys[InputKeyUp]-(g->keys[InputKeyDown]&&!combo));float x=g->x+cosf(g->a)*speed,y=g->y+sinf(g->a)*speed;if(!wall(x,g->y))g->x=x;if(!wall(g->x,y))g->y=y;if(speed!=0)g->phase++;else g->phase=0;if(g->ride>=0){g->vx[g->ride]=g->x;g->vy[g->ride]=g->y;}float target=g->mission%2?1.5f:14.5f;if(fabsf(g->x-target)<.6f&&fabsf(g->y-target)<.6f){g->cash+=250;g->mission++;}furi_mutex_release(g->lock);view_port_update(v);}gui_remove_view_port(gui,v);view_port_free(v);furi_record_close(RECORD_GUI);furi_message_queue_free(g->q);furi_mutex_free(g->lock);free(g);return 0;}